-- Complete the page-level alignment for lessons 1, 2, 8, 10 and 11 of Medina volume 3.
begin;

update public.rules
set lesson_number = '2'
where course_name = 'Мединский курс (Том 3)'
  and (
    title like 'وَاوُ الْحَالِ%'
    or title like 'لَعَلَّ%'
    or title like 'اسْمُ الْفِعْلِ%'
    or title like 'مِنَ الزَّائِدَةُ%'
    or title like 'لَدَى%'
    or title like 'مَنْعُ أَشْيَاءَ%'
  );

with extra (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('1', 121, 'الِاسْمُ الْمَقْصُورُ (Имя с конечным алифом)',
   'Склонение имён на ا и ى с невидимыми окончаниями.',
   'В الِاسْمُ الْمَقْصُورُ конечный алиф не принимает огласовку. Поэтому падежные признаки во всех трёх падежах считаются تقديرية — предполагаемыми, но не видимыми: فَتًى، رَأَيْتُ فَتًى، مَرَرْتُ بِفَتًى. Танвин фатха при неопределённости пишется, а сам алиф остаётся частью основы.',
   '<li><span dir="rtl" lang="ar">جَاءَ فَتًى مُهَذَّبٌ</span> — пришёл воспитанный юноша.</li><li><span dir="rtl" lang="ar">رَأَيْتُ فَتًى مُهَذَّبًا</span> — я увидел воспитанного юношу.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِفَتًى مُهَذَّبٍ</span> — я прошёл мимо воспитанного юноши.</li>',
   '<span dir="rtl" lang="ar">فَتًى: فَاعِلٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ، وَمُهَذَّبٌ نَعْتٌ مَرْفُوعٌ.</span><br><span dir="rtl" lang="ar">فَتًى: مَفْعُولٌ بِهِ مَنْصُوبٌ بِفَتْحَةٍ مُقَدَّرَةٍ.</span><br><span dir="rtl" lang="ar">فَتًى: اسْمٌ مَجْرُورٌ بِكَسْرَةٍ مُقَدَّرَةٍ.</span>'),
  ('1', 122, 'الِاسْمُ الْمَنْقُوصُ (Неполное имя на ياء)',
   'Склонение имени с конечной ياء, перед которой стоит كسرة.',
   'В неопределённых رفع и جر конечная ياء الِاسْمُ الْمَنْقُوصُ обычно опускается, а ضمة и كسرة считаются تقديرية. В نصب ياء сохраняется и появляется явная фатха: جَاءَ قَاضٍ، رَأَيْتُ قَاضِيًا، مَرَرْتُ بِقَاضٍ. При определённости ياء сохраняется: جَاءَ الْقَاضِي.',
   '<li><span dir="rtl" lang="ar">جَاءَ قَاضٍ عَادِلٌ</span> — пришёл справедливый судья.</li><li><span dir="rtl" lang="ar">رَأَيْتُ قَاضِيًا عَادِلًا</span> — я увидел справедливого судью.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِقَاضٍ عَادِلٍ</span> — я прошёл мимо справедливого судьи.</li>',
   '<span dir="rtl" lang="ar">قَاضٍ: فَاعِلٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ عَلَى الْيَاءِ الْمَحْذُوفَةِ.</span><br><span dir="rtl" lang="ar">قَاضِيًا: مَفْعُولٌ بِهِ مَنْصُوبٌ بِفَتْحَةٍ ظَاهِرَةٍ.</span><br><span dir="rtl" lang="ar">قَاضٍ: اسْمٌ مَجْرُورٌ بِكَسْرَةٍ مُقَدَّرَةٍ.</span>'),
  ('1', 123, 'الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ (Имя, присоединённое к ياء говорящего)',
   'Имена типа كِتَابِي и صَدِيقِي с особым произношением окончаний.',
   'При присоединении имени к ياءِ الْمُتَكَلِّمِ окончание основы скрывается перед долгим и: هَذَا كِتَابِي، رَأَيْتُ كِتَابِي، نَظَرْتُ فِي كِتَابِي. Падеж определяется синтаксической ролью, но ضمة и كسرة перед ياء считаются مقدرتين; форма ياء المتكلم сама является مضافاً إليه.',
   '<li><span dir="rtl" lang="ar">هَذَا كِتَابِي</span> — это моя книга.</li><li><span dir="rtl" lang="ar">قَرَأْتُ كِتَابِي</span> — я прочитал свою книгу.</li><li><span dir="rtl" lang="ar">نَظَرْتُ فِي كِتَابِي</span> — я посмотрел в свою книгу.</li>',
   '<span dir="rtl" lang="ar">كِتَابِي: خَبَرٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ، وَالْيَاءُ مَضَافٌ إِلَيْهِ.</span><br><span dir="rtl" lang="ar">كِتَابِي: مَفْعُولٌ بِهِ مَنْصُوبٌ بِفَتْحَةٍ مُقَدَّرَةٍ.</span><br><span dir="rtl" lang="ar">كِتَابِي: اسْمٌ مَجْرُورٌ بِكَسْرَةٍ مُقَدَّرَةٍ.</span>'),
  ('8', 124, 'أَقْسَامُ الْمَعْرِفَةِ (Семь видов определённого имени)',
   'Классификация معرفَة по способу определённости.',
   'К معرفَة относятся الضَّمِيرُ, العَلَمُ, اسْمُ الْإِشَارَةِ, اسْمُ الْمَوْصُولِ, имя с ال, مضاف к معرفة и النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ. Такая классификация нужна для правильного понимания роли слова и для определения условий, при которых допустим неопределённый مبتدأ.',
   '<li><span dir="rtl" lang="ar">أَنَا طَالِبٌ</span> — я студент; местоимение.</li><li><span dir="rtl" lang="ar">جَاءَ مُحَمَّدٌ</span> — пришёл Мухаммад; имя собственное.</li><li><span dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ</span> — это книга студента; указательное имя и إضافة.</li>',
   '<span dir="rtl" lang="ar">أَنَا: ضَمِيرٌ مَبْنِيٌّ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٍ.</span><br><span dir="rtl" lang="ar">مُحَمَّدٌ: فَاعِلٌ مَرْفُوعٌ بِالضَّمَّةِ.</span><br><span dir="rtl" lang="ar">هَذَا: مُبْتَدَأٌ مَرْفُوعٌ، وَكِتَابُ مَضَافٌ، وَالطَّالِبِ مَضَافٌ إِلَيْهِ.</span>'),
  ('8', 125, 'النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ (Неопределённое имя, определённое обращением)',
   'Обращение к конкретному лицу меняет синтаксическое оформление неопределённого имени.',
   'Если говорящий обращается к конкретному обладателю качества, النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ строится как معرفة и получает ضمة: يَا طَالِبُ. Если обращение не адресовано конкретному лицу, слово остаётся نكرة منصوبة: يَا طَالِبًا، أَعِنِّي. Различие определяется смыслом, а не только формой.',
   '<li><span dir="rtl" lang="ar">يَا طَالِبُ، اجْتَهِدْ</span> — студент, усердно занимайся.</li><li><span dir="rtl" lang="ar">يَا رَجُلُ، أَقْبِلْ</span> — мужчина, подойди; обращение к конкретному человеку.</li><li><span dir="rtl" lang="ar">يَا رَجُلًا خُذْ بِيَدِي</span> — о мужчина, помоги мне; обращение не к определённому лицу.</li>',
   '<span dir="rtl" lang="ar">طَالِبُ: مُنَادًى نَكِرَةٌ مَقْصُودَةٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ نَصْبٍ.</span><br><span dir="rtl" lang="ar">رَجُلُ: مُنَادًى نَكِرَةٌ مَقْصُودَةٌ مَبْنِيٌّ عَلَى الضَّمِّ.</span><br><span dir="rtl" lang="ar">رَجُلًا: مُنَادًى نَكِرَةٌ غَيْرُ مَقْصُودَةٍ مَنْصُوبٌ بِالْفَتْحَةِ.</span>'),
  ('10', 126, 'إِنَّ وَأَخَوَاتُهَا (Частицы, подобные глаголам)',
   'Частицы إِنَّ، أَنَّ، كَأَنَّ، لَكِنَّ، لَيْتَ، لَعَلَّ и لَا النَّافِيَةُ لِلْجِنْسِ.',
   'Эти частицы входят в именное предложение: اسمها становится منصوبом, а خبرها остаётся مرفوعом. Значение зависит от частицы: إِنَّ — утверждение, لَيْتَ — пожелание, لَعَلَّ — надежда или опасение, كَأَنَّ — уподобление. Смысловую роль частицы нужно отличать от падежной роли двух членов.',
   '<li><span dir="rtl" lang="ar">إِنَّ الطَّالِبَ مُجْتَهِدٌ</span> — действительно, студент усерден.</li><li><span dir="rtl" lang="ar">لَيْتَ السَّفَرَ قَرِيبٌ</span> — если бы путешествие было близко.</li><li><span dir="rtl" lang="ar">لَعَلَّ الْمَرِيضَ مُعَافًى</span> — возможно, больной выздоровел.</li>',
   '<span dir="rtl" lang="ar">الطَّالِبَ: اسْمُ إِنَّ مَنْصُوبٌ بِالْفَتْحَةِ، وَمُجْتَهِدٌ خَبَرُهَا مَرْفُوعٌ.</span><br><span dir="rtl" lang="ar">السَّفَرَ: اسْمُ لَيْتَ مَنْصُوبٌ، وَقَرِيبٌ خَبَرُهَا مَرْفُوعٌ.</span><br><span dir="rtl" lang="ar">الْمَرِيضَ: اسْمُ لَعَلَّ مَنْصُوبٌ، وَمُعَافًى خَبَرُهَا مَرْفُوعٌ.</span>'),
  ('10', 127, 'كَانَ وَأَخَوَاتُهَا (Неполнозначные глаголы)',
   'Глаголы, которые входят в именное предложение и меняют его падежное управление.',
   'كَانَ وأخواتها называют الأفعال الناقصة: اسمها остаётся مرفوعом, а خبر становится منصوبом. Они передают время, продолжение, переход и другие оттенки состояния: كَانَ، أَصْبَحَ، أَمْسَى، ظَلَّ، بَاتَ، لَيْسَ، مَا زَالَ. Глагол согласуется с именем, а خبر может быть словом, предложением или شبه جملة.',
   '<li><span dir="rtl" lang="ar">كَانَ الْجَوُّ مُعْتَدِلًا</span> — погода была умеренной.</li><li><span dir="rtl" lang="ar">أَصْبَحَ الطَّالِبُ نَشِيطًا</span> — студент стал бодрым.</li><li><span dir="rtl" lang="ar">لَيْسَ الْكِتَابُ بَعِيدًا</span> — книга не далеко.</li>',
   '<span dir="rtl" lang="ar">الْجَوُّ: اسْمُ كَانَ مَرْفُوعٌ، وَمُعْتَدِلًا خَبَرُهَا مَنْصُوبٌ.</span><br><span dir="rtl" lang="ar">الطَّالِبُ: اسْمُ أَصْبَحَ مَرْفُوعٌ، وَنَشِيطًا خَبَرُهَا مَنْصُوبٌ.</span><br><span dir="rtl" lang="ar">الْكِتَابُ: اسْمُ لَيْسَ مَرْفُوعٌ، وَبَعِيدًا خَبَرُهَا مَنْصُوبٌ.</span>'),
  ('10', 128, 'أَفْعَالُ الشُّرُوعِ (Глаголы начала действия)',
   'طَفِقَ، جَعَلَ، أَخَذَ، شَرَعَ и сходные глаголы с مضارع в роли сказуемого.',
   'Аفعال الشروع сообщают о начале действия. Они работают как كَانَ: имя остаётся مرفوعом, а خبر становится منصوبом. Однако خبر после них обычно выражается настоящим временем без أنْ: شَرَعَ الطَّالِبُ يَقْرَأُ. Это отличает их от обычного переходного значения тех же глаголов вне данной конструкции.',
   '<li><span dir="rtl" lang="ar">شَرَعَ الطَّالِبُ يَقْرَأُ</span> — студент начал читать.</li><li><span dir="rtl" lang="ar">أَخَذَ الْمُعَلِّمُ يَشْرَحُ الدَّرْسَ</span> — учитель начал объяснять урок.</li><li><span dir="rtl" lang="ar">طَفِقَ الطِّفْلُ يَلْعَبُ</span> — ребёнок принялся играть.</li>',
   '<span dir="rtl" lang="ar">الطَّالِبُ: اسْمُ شَرَعَ مَرْفُوعٌ، وَجُمْلَةُ يَقْرَأُ خَبَرُهَا فِي مَحَلِّ نَصْبٍ.</span><br><span dir="rtl" lang="ar">الْمُعَلِّمُ: اسْمُ أَخَذَ مَرْفُوعٌ، وَجُمْلَةُ يَشْرَحُ خَبَرُهَا فِي مَحَلِّ نَصْبٍ.</span><br><span dir="rtl" lang="ar">الطِّفْلُ: اسْمُ طَفِقَ مَرْفُوعٌ، وَجُمْلَةُ يَلْعَبُ خَبَرُهَا فِي مَحَلِّ نَصْبٍ.</span>'),
  ('11', 129, 'أَقْسَامُ الْخَبَرِ (Виды сказуемого)',
   'خبر бывает одиночным словом, предложением или شبه جملة.',
   'Одиночный خبر — это не обязательно одно слово по смыслу, а форма, не являющаяся предложением или شبه جملة. جملة اسمية и جملة فعلية должны иметь رابط, связывающий их с مبتدأ. شبه جملة состоит из جار ومجرور или ظرف и обычно относится к подразумеваемому сказуемому.',
   '<li><span dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ</span> — студент усердный; одиночное сказуемое.</li><li><span dir="rtl" lang="ar">الطَّالِبُ أَخْلَاقُهُ كَرِيمَةٌ</span> — нрав студента благороден; именное предложение.</li><li><span dir="rtl" lang="ar">الطَّالِبُ فِي الْفَصْلِ</span> — студент в классе; شبه جملة.</li>',
   '<span dir="rtl" lang="ar">مُجْتَهِدٌ: خَبَرٌ مَرْفُوعٌ.</span><br><span dir="rtl" lang="ar">أَخْلَاقُهُ كَرِيمَةٌ: جُمْلَةٌ اسْمِيَّةٌ فِي مَحَلِّ رَفْعٍ خَبَرٌ.</span><br><span dir="rtl" lang="ar">فِي الْفَصْلِ: جَارٌّ وَمَجْرُورٌ مُتَعَلِّقٌ بِخَبَرٍ مَحْذُوفٍ فِي مَحَلِّ رَفْعٍ.</span>'),
  ('11', 130, 'حَذْفُ الْخَبَرِ (Опущение сказуемого)',
   'خبر может быть опущен, если его содержание однозначно восстанавливается.',
   'Опущение الخبر допустимо в кратком ответе, устойчивой формуле и контексте, где вопрос уже содержит признак или место. В и‘раб указывается: الخبر محذوف تقديره ... . Нельзя удалять сказуемое произвольно: восстановление должно быть очевидным для слушателя.',
   '<li><span dir="rtl" lang="ar">مَنْ فِي الْبَابِ؟ — أَنَا</span> — кто у двери? — я.</li><li><span dir="rtl" lang="ar">كَيْفَ أَنْتَ؟ — بِخَيْرٍ</span> — как ты? — хорошо.</li><li><span dir="rtl" lang="ar">أَيْنَ الطَّالِبُ؟ — فِي الْفَصْلِ</span> — где студент? — в классе.</li>',
   '<span dir="rtl" lang="ar">أَنَا: مُبْتَدَأٌ مَرْفُوعٌ، وَالْخَبَرُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ.</span><br><span dir="rtl" lang="ar">بِخَيْرٍ: جَارٌّ وَمَجْرُورٌ خَبَرٌ لِمُبْتَدَأٍ مَحْذُوفٍ.</span><br><span dir="rtl" lang="ar">فِي الْفَصْلِ: شِبْهُ جُمْلَةٍ خَبَرٌ لِمُبْتَدَأٍ مَحْذُوفٍ.</span>'),
  ('11', 131, 'مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَإِ (Согласование сказуемого с مبتدأ)',
   'Сказуемое согласуется с подлежащим в роде и числе в пределах правил арабского синтаксиса.',
   'При одиночном خبر согласуются род и число: مُفْرَد، مُثَنَّى، جَمْع. В именном предложении с неодушевлённым множественным числом сказуемое часто имеет форму женского рода единственного числа. При глагольном предложении порядок слов влияет на согласование глагола.',
   '<li><span dir="rtl" lang="ar">الطَّالِبَةُ مُجْتَهِدَةٌ</span> — студентка усердна.</li><li><span dir="rtl" lang="ar">الطَّالِبَانِ حَاضِرَانِ</span> — два студента присутствуют.</li><li><span dir="rtl" lang="ar">الطَّالِبَاتُ مُجْتَهِدَاتٌ</span> — студентки усердны.</li>',
   '<span dir="rtl" lang="ar">مُجْتَهِدَةٌ: خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ.</span><br><span dir="rtl" lang="ar">حَاضِرَانِ: خَبَرٌ مَرْفُوعٌ بِالْأَلِفِ لِأَنَّهُ مُثَنًّى.</span><br><span dir="rtl" lang="ar">مُجْتَهِدَاتٌ: خَبَرٌ مَرْفُوعٌ بِالضَّمَّةِ، وَهُوَ جَمْعُ مُؤَنَّثٍ سَالِمٌ.</span>'),
  ('11', 132, 'حَذْفُ الْمُبْتَدَإِ وَالْخَبَرِ مَعًا (Одновременное опущение двух членов)',
   'Оба члена предложения могут опускаться в кратком ответе при полном восстановлении смысла.',
   'Если контекст уже содержит вопрос и ответ, арабский язык допускает حذف المبتدأ والخبر معاً. В и‘раб сохраняется связь с подразумеваемой конструкцией, а не объявляется ответ бессвязным. Пример نعم на вопрос أطالب أنت؟ означает نعم، أنا طالبٌ.',
   '<li><span dir="rtl" lang="ar">أَأَنْتَ طَالِبٌ؟ — نَعَمْ</span> — ты студент? — да.</li><li><span dir="rtl" lang="ar">أَفِي الْفَصْلِ الْمُدِيرُ؟ — نَعَمْ</span> — директор в классе? — да.</li><li><span dir="rtl" lang="ar">أَهَذَا كِتَابُكَ؟ — لَا</span> — это твоя книга? — нет.</li>',
   '<span dir="rtl" lang="ar">نَعَمْ: جَوَابٌ مُخْتَصَرٌ، وَالتَّقْدِيرُ نَعَمْ أَنَا طَالِبٌ.</span><br><span dir="rtl" lang="ar">نَعَمْ: التَّقْدِيرُ نَعَمْ الْمُدِيرُ فِي الْفَصْلِ.</span><br><span dir="rtl" lang="ar">لَا: التَّقْدِيرُ لَا، هَذَا لَيْسَ كِتَابِي.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select 'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إعراب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from extra
where not exists (
  select 1 from public.rules r
  where r.course_name = 'Мединский курс (Том 3)' and r.title = extra.title
);

commit;
